import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"命令行","description":"","frontmatter":{},"headers":[],"relativePath":"zh/developers/cli.md","filePath":"zh/developers/cli.md","lastUpdated":1793111003000}'),d={name:"zh/developers/cli.md"};function o(h,e,p,l,n,r){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="命令行" tabindex="-1">命令行 <a class="header-anchor" href="#命令行" aria-label="Permalink to &quot;命令行&quot;">​</a></h1><p><code>paperseek</code> 命令与 Web 界面使用相同的应用服务。执行真实检索前，先在进程环境中配置模型与数据源凭据。</p><h2 id="六个命令" tabindex="-1">六个命令 <a class="header-anchor" href="#六个命令" aria-label="Permalink to &quot;六个命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>serve</code></td><td>启动本地 HTTP 服务，默认同时启动 worker</td></tr><tr><td><code>worker</code></td><td>使用指定本地数据库运行独立 worker</td></tr><tr><td><code>search</code></td><td>在终端执行问题并返回 JSON</td></tr><tr><td><code>doctor</code></td><td>输出配置与安装诊断</td></tr><tr><td><code>migrate</code></td><td>迁移本地数据或转换旧配置</td></tr><tr><td><code>version</code></td><td>显示安装版本</td></tr></tbody></table><p>使用 <code>paperseek &lt;命令&gt; --help</code> 查看当前安装的完整参数。</p><h2 id="执行检索" tabindex="-1">执行检索 <a class="header-anchor" href="#执行检索" aria-label="Permalink to &quot;执行检索&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;How does open-source funding affect maintenance?&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openalex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --search-budget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> medium</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>数据源 ID：<code>openalex</code>、<code>arxiv</code>、<code>crossref</code>、<code>semanticscholar</code>、<code>pubmed</code>、<code>wos</code>、<code>googlescholar</code>、<code>paperhub</code>。</p><p>预算使用 <code>fast</code>、<code>medium</code>、<code>high</code>、<code>max</code>。支持学科筛选的数据源使用 <code>--field-id</code>；文本范围提示使用 <code>--field-hint</code>；支持引用扩展时，可用 <code>--citation-enabled</code> 或 <code>--no-citation-enabled</code> 控制。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Efficient long-context language models&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arxiv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --field-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cs.CL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --search-budget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fast</span></span></code></pre></div><p>模型覆盖参数包括 <code>--llm-provider</code>、<code>--llm-api-type</code>、<code>--llm-model</code> 和 <code>--llm-base-url</code>。密钥应从环境读取，避免把真实值写入命令历史。</p><h2 id="指定数据库" tabindex="-1">指定数据库 <a class="header-anchor" href="#指定数据库" aria-label="Permalink to &quot;指定数据库&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --database</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/paperseek/paperseek.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --database</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/paperseek/paperseek.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8765</span></span></code></pre></div><p>默认路径为 <code>~/.paperseek/paperseek.db</code>。需要 Web、CLI 和 MCP 访问同一批历史时，请统一数据库路径。</p><p>诊断报告可用于检查缺失配置，但不代表后续每次上游请求都会成功。另见<a href="./../reference/configuration">配置参考</a>与<a href="./../self-hosting/upgrade">迁移指南</a>。</p>`,15)])])}const F=s(d,[["render",o]]);export{k as __pageData,F as default};
